Object.assign(TEXT.ta,{itemSaved:'பொருள் சேமிக்கப்பட்டது',ownerCatalogOnly:'கடை உரிமையாளர் / நிர்வாகி மட்டுமே பொருள் பட்டியல், விலைகள் மற்றும் UPI விவரங்களை மாற்றலாம்.',staffManagement:'பணியாளர் அணுகல்',staffManagementHint:'பணியாளரை அழைக்க பெயர் மற்றும் மின்னஞ்சலை உள்ளிடவும். அவர்களே கடவுச்சொல்லை அமைக்க மின்னஞ்சல் வரும்.',staffEmail:'பணியாளர் கணக்கு மின்னஞ்சல்',staffName:'பணியாளர் பெயர்',addStaffMember:'பணியாளர் உள்நுழைவை உருவாக்கு',currentStaff:'தற்போதைய பணியாளர்கள்',staffAdded:'ஏற்கனவே உள்ள கணக்கு பணியாளராகச் சேர்க்கப்பட்டது.',staffInvitationSent:'பணியாளர் அழைப்பு மின்னஞ்சல் அனுப்பப்பட்டது. அதில் கடவுச்சொல்லை அமைத்து உள்நுழையலாம்.',noStaffMembers:'பணியாளர்கள் இன்னும் சேர்க்கப்படவில்லை.',staffAccountMissing:'இந்த மின்னஞ்சலுக்கு கணக்கு இல்லை. மின்னஞ்சலைச் சரிபார்க்கவும் அல்லது மீண்டும் அழைக்கவும்.',staffAlreadyAdded:'இந்தக் கணக்கு ஏற்கனவே இந்தக் கடையில் உள்ளது.',staffNameRequired:'பணியாளர் பெயரை உள்ளிடவும்.',staffEmailRequired:'சரியான பணியாளர் மின்னஞ்சலை உள்ளிடவும்.',staffEmailPlaceholder:'staff@example.com',staffNamePlaceholder:'எ.கா. குமார்',staffInviteUnavailable:'பணியாளர் உள்நுழைவை உருவாக்க முடியவில்லை. invite-shop-staff Supabase செயல்பாடு deploy செய்யப்பட்டுள்ளதா, மின்னஞ்சல் அழைப்புகள் அமைக்கப்பட்டுள்ளதா எனச் சரிபார்க்கவும்.',staffInvitePartial:'கணக்கு அழைப்பு அனுப்பப்பட்டது; ஆனால் கடை அணுகலை இணைக்க முடியவில்லை. பயனர் அழைப்பை ஏற்ற பிறகு இந்த மின்னஞ்சலை மீண்டும் சேர்க்கவும்.',sendingStaffInvite:'அழைப்பு அனுப்பப்படுகிறது…',itemFormSubtitle:'கடைப் பொருள் விவரங்களையும் விலையையும் புதுப்பிக்கவும்.'});
