function useSelectedDefaultItem(){const chosen=DEFAULT_ITEMS.find(item=>catalogDefaultItems.has(item.name));if(!chosen){showToast(t('selectDefaultItem'));return}if(state.items.some(item=>item.name.trim().toLowerCase()===chosen.name.toLowerCase())){showToast(t('itemExists'));return}$('newItemName').value=chosen.name;$('newItemTamil').value=chosen.tamil;$('newItemPrice').value='';catalogDefaultItems.clear();$('defaultItemsDialog').close();$('newItemPrice').focus()}
