function setShopSetupTab(tab){const catalog=tab==='catalog';$('shopDetailsPanel').hidden=catalog;$('itemCatalogPanel').hidden=!catalog;$('shopDetailsTab').classList.toggle('active',!catalog);$('itemCatalogTab').classList.toggle('active',catalog);$('shopDetailsTab').setAttribute('aria-selected',String(!catalog));$('itemCatalogTab').setAttribute('aria-selected',String(catalog));if(catalog){renderDefaultItemOptions('setupDefaultItems',setupDefaultItems);renderSetupCatalogItems()}}
async function authRequest(path,body){const r=await fetch(`${cloudConfig.SUPABASE_URL.replace(/\/$/,'')}/auth/v1/${path}`,{method:'POST',headers:{'Content-Type':'application/json','apikey':cloudConfig.SUPABASE_PUBLISHABLE_KEY},body:JSON.stringify(body)});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||d.msg||'Sign in failed');return d}
async function refreshAuth(){if(!cloudSession?.refresh_token)return false;try{cloudSession=await authRequest('token?grant_type=refresh_token',{refresh_token:cloudSession.refresh_token});localStorage.setItem('kb-auth-session',JSON.stringify(cloudSession));return true}catch{cloudSession=null;localStorage.removeItem('kb-auth-session');return false}}
function newId(){if(crypto.randomUUID)return crypto.randomUUID();return'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)})}
function readJson(key,fallback){try{return JSON.parse(localStorage.getItem(key)||'null')||fallback}catch{return fallback}}
function pendingBills(){return readJson('kb-pending-bills',[])}
function savePendingBills(rows){localStorage.setItem('kb-pending-bills',JSON.stringify(rows))}
function cacheKey(uid,shopId){return`kb-cloud-cache:${uid}:${shopId}`}
function pendingFor(uid=cloudSession?.user?.id,shopId=cloudShopId){return pendingBills().filter(b=>b.user_id===uid&&b.shop_id===shopId)}
function updateSyncStatus(){if(!cloudMode)return;const count=pendingFor().length;const el=$('syncStatus');el.hidden=false;el.textContent=cloudOnline?(count?`${t('syncing')} · ${count} ${t('pending')}`:t('synced')):`${t('offline')} · ${count} ${t('pending')}`;el.classList.toggle('offline',!cloudOnline);renderBillNo()}
function mergePendingBills(){const queued=pendingFor().map(p=>({...p.bill,id:p.local_id,number:p.bill.number,pending:true,shopId:p.shop_id}));const ids=new Set(queued.map(b=>b.id));state.bills=[...queued,...state.bills.filter(b=>!ids.has(b.id))]}
async function cloudApi(path,{method='GET',body,prefer}={}){const send=()=>fetch(`${cloudConfig.SUPABASE_URL.replace(/\/$/,'')}/rest/v1/${path}`,{method,headers:{'apikey':cloudConfig.SUPABASE_PUBLISHABLE_KEY,'Authorization':`Bearer ${cloudSession.access_token}`,'Content-Type':'application/json',...(prefer?{Prefer:prefer}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});let r;try{r=await send()}catch(e){e.isNetworkError=true;throw e}if(r.status===401){if(await refreshAuth()){try{r=await send()}catch(e){e.isNetworkError=true;throw e}}else{expireCloudSession();const e=new Error('Your session expired. Sign in again.');e.status=401;throw e}}const data=await r.json().catch(()=>null);if(!r.ok){const e=new Error(data?.message||data?.hint||data?.details||'Cloud request failed');e.status=r.status;throw e}return data}
function expireCloudSession(){cloudLoadVersion++;cloudSession=null;cloudMode=false;cloudOnline=false;localStorage.removeItem('kb-auth-session');$('appShell').hidden=true;$('authGate').hidden=false;$('signOut').hidden=true;clearAuthMessages();showAuthTab('login');cart=[];state.items=[];state.bills=[];renderAll()}
function showCloudData(){const uid=cloudSession.user.id;const remembered=localStorage.getItem('kb-active-shop-id');if(!cloudShops.some(s=>s.id===cloudShopId))cloudShopId=cloudShops.some(s=>s.id===remembered)?remembered:cloudShops[0]?.id;if(!cloudShopId)return false;localStorage.setItem('kb-active-shop-id',cloudShopId);cloudMember=cloudShops.find(s=>s.id===cloudShopId)?.membership||cloudMember;const shop=cloudShops.find(s=>s.id===cloudShopId);const select=$('shopSelect');select.innerHTML=cloudShops.map(s=>`<option value="${escapeHtml(s.id)}">${escapeHtml(s.name)}</option>`).join('');select.value=cloudShopId;$('shopSwitch').hidden=false;$('shopSettingsButton').hidden=false;$('shopLabel').textContent=shop?.name||t('shop');mergePendingBills();renderAll();renderBillNo();$('staffDisplayName').textContent=cloudMember?.display_name||t('staffNameLabel');$('staffTop').textContent=initials(cloudMember?.display_name||t('staffNameLabel'));$('staffMenu').hidden=true;$('staffTop').onclick=null;translateStaticUi();updateSyncStatus();return true}
function updateSignedInRole(){const role=$('signedInRole');const isSignedIn=cloudMode&&!!cloudMember?.role;role.hidden=!isSignedIn;if(isSignedIn)role.textContent=t(cloudMember.role==='owner'?'ownerRole':'staffRole');$('shopSettingsButton').hidden=!isSignedIn}
function openOfflineCache(session){const uid=session.user.id;const shops=readJson(`kb-cloud-shops:${uid}`,[]);if(!shops.length)return false;cloudSession=session;cloudMode=true;cloudOnline=false;cloudShops=shops;const remembered=localStorage.getItem('kb-active-shop-id');const cachedShop=shops.find(s=>s.id===remembered&&readJson(cacheKey(uid,s.id),null))||shops.find(s=>readJson(cacheKey(uid,s.id),null));if(!cachedShop)return false;cloudShopId=cachedShop.id;const cached=readJson(cacheKey(uid,cloudShopId),null);cloudMember=shops.find(s=>s.id===cloudShopId)?.membership;state.items=cached.items||[];state.bills=cached.bills||[];$('authGate').hidden=true;$('appShell').hidden=false;$('signOut').hidden=false;showCloudData();showToast(t('offlineMode'));return true}
async function loadOfflineShop(shopId){const cached=readJson(cacheKey(cloudSession.user.id,shopId),null);if(!cached)throw new Error(t('noOfflineCatalog'));cloudShopId=shopId;cloudMember=cloudShops.find(s=>s.id===shopId)?.membership;state.items=cached.items||[];state.bills=cached.bills||[];showCloudData()}
async function loadCloudData(){const loadVersion=++cloudLoadVersion;const uid=cloudSession.user.id;try{const memberships=await cloudApi(`shop_members?user_id=eq.${encodeURIComponent(uid)}&select=shop_id,display_name,role`);if(loadVersion!==cloudLoadVersion)return;if(!memberships?.length)throw new Error('This account has not been approved for a shop yet. Ask the owner to assign it.');const shops=await cloudApi('shops?select=id,business_id,name,upi_id,address,phone&order=name.asc');if(loadVersion!==cloudLoadVersion)return;const membershipByShop=new Map(memberships.map(m=>[m.shop_id,m]));cloudShops=(shops||[]).filter(s=>membershipByShop.has(s.id)).map(s=>({...s,membership:membershipByShop.get(s.id)}));if(!cloudShops.length)throw new Error('No accessible shops were found for this login.');const remembered=localStorage.getItem('kb-active-shop-id');if(!cloudShops.some(s=>s.id===cloudShopId))cloudShopId=cloudShops.some(s=>s.id===remembered)?remembered:cloudShops[0].id;localStorage.setItem('kb-active-shop-id',cloudShopId);const shopId=cloudShopId;const [members,items,bills,lines,upiRequests]=await Promise.all([cloudApi(`shop_members?shop_id=eq.${shopId}&select=user_id,display_name,role`),cloudApi(`items?shop_id=eq.${shopId}&deleted=eq.false&select=id,name,name_ta,price&order=name.asc`),cloudApi(`bills?shop_id=eq.${shopId}&deleted=eq.false&select=id,bill_number,customer_name,customer_mobile,subtotal,discount,total,created_at,created_by&order=created_at.desc&limit=100`),cloudApi(`bill_items?shop_id=eq.${shopId}&select=id,bill_id,item_id,item_name,item_name_ta,quantity,unit_price,line_total`),cloudApi(`shop_upi_change_requests?shop_id=eq.${shopId}&status=eq.pending&select=id,requested_by,new_upi_id,created_at&order=created_at.asc`)]);if(loadVersion!==cloudLoadVersion)return;cloudMembers=members||[];cloudUpiRequests=upiRequests||[];$('shopSettingsButton').textContent=cloudMember?.role==='owner'&&cloudUpiRequests.length?`Shop setup · ${cloudUpiRequests.length} approval${cloudUpiRequests.length===1?'':'s'}`:'Shop setup';const names=Object.fromEntries(cloudMembers.map(m=>[m.user_id,m.display_name]));state.items=(items||[]).map(i=>({id:i.id,name:i.name,tamil:i.name_ta||'',price:Number(i.price)}));state.bills=(bills||[]).map(b=>({id:b.id,shopId,number:b.bill_number,customer:b.customer_name||'',mobile:b.customer_mobile||'',staff:names[b.created_by]||'Shop staff',subtotal:Number(b.subtotal),discount:Number(b.discount),total:Number(b.total),createdAt:b.created_at,items:(lines||[]).filter(x=>x.bill_id===b.id).map(x=>({id:x.item_id,name:x.item_name,tamil:x.item_name_ta||'',qty:Number(x.quantity),price:Number(x.unit_price)}))}));cloudMember=membershipByShop.get(shopId);cloudOnline=true;try{localStorage.setItem(`kb-cloud-shops:${uid}`,JSON.stringify(cloudShops));localStorage.setItem(cacheKey(uid,shopId),JSON.stringify({items:state.items,bills:state.bills,updated_at:new Date().toISOString()}))}catch{}showCloudData();if($('shopDialog').open)renderShopDialog()}catch(e){if(e.isNetworkError){cloudOnline=false;updateSyncStatus()}throw e}}
async function syncPendingBills(){if(!cloudMode||!cloudOnline||!cloudSession?.user?.id)return;const uid=cloudSession.user.id;let rows=pendingBills();let changed=false;for(const entry of rows.filter(p=>p.user_id===uid&&cloudShops.some(s=>s.id===p.shop_id))){try{const submit=snapshotOnly=>cloudApi('rpc/create_shop_bill',{method:'POST',body:{p_shop_id:entry.shop_id,p_customer_name:entry.bill.customer||null,p_customer_mobile:entry.bill.mobile||null,p_discount:entry.bill.discount,p_items:entry.bill.items.map(i=>({item_id:snapshotOnly?null:i.id,item_name:i.name,item_name_ta:i.tamil||null,quantity:i.qty,unit_price:i.price,line_total:i.qty*i.price})),p_client_request_id:entry.local_id}});try{await submit(false)}catch(first){if(first.status>=400&&first.status<500&&/not in this shop catalog/i.test(first.message))await submit(true);else throw first}rows=rows.filter(p=>p.local_id!==entry.local_id);changed=true;savePendingBills(rows)}catch(e){if(e.isNetworkError){cloudOnline=false;updateSyncStatus();break}entry.sync_error=e.message;rows=rows.map(p=>p.local_id===entry.local_id?entry:p);savePendingBills(rows);changed=true;showToast(`Pending bill needs attention: ${e.message}`);break}}if(changed&&cloudOnline){await loadCloudData()}else{mergePendingBills();updateSyncStatus();renderAll()}}

function renderShopDialog(){const shop=cloudShops.find(s=>s.id===cloudShopId);if(!shop)return;const activeTab=$('itemCatalogPanel').hidden?'details':'catalog';const owner=cloudMember?.role==='owner';ensureStaffManagementPanel();$('shopDialogTitle').textContent=`${shop.name} · ${t('shopSetup')}`;$('shopUpiCurrent').textContent=shop.upi_id?`${t('currentUpi')}: ${shop.upi_id}`:t('upiNotAdded');$('shopUpiInput').value=shop.upi_id||'';$('shopUpiInput').disabled=!owner;$('saveShopUpi').textContent=owner?(shop.upi_id?t('updateUpi'):t('addUpi')):t('requestUpi');$('upiHelp').textContent=owner?t('ownerUpiHelp'):t('staffUpiHelp');$('upiRequestsPanel').hidden=!owner;$('registerShopPanel').hidden=!owner;$('staffManagementPanel').hidden=!owner;$('setupDefaultItems').hidden=!owner;$('addSetupDefaultItems').hidden=!owner;document.querySelector('#itemCatalogPanel > .subheading').hidden=!owner;document.querySelector('#itemCatalogPanel [data-t="editCatalogHeading"]').hidden=!owner;document.querySelector('#itemCatalogPanel [data-t="editCatalogHint"]').hidden=!owner;$('shopStaffList').innerHTML=cloudMembers.filter(member=>member.role==='staff').map(member=>`<li>${escapeHtml(member.display_name)}</li>`).join('')||`<li>${t('noStaffMembers')}</li>`;document.querySelectorAll('#staffManagementPanel [data-t]').forEach(el=>el.textContent=t(el.dataset.t));document.querySelectorAll('#staffManagementPanel [data-ph]').forEach(el=>el.placeholder=t(el.dataset.ph));$('upiRequestsList').innerHTML=cloudUpiRequests.length?cloudUpiRequests.map(r=>{const requester=cloudMembers.find(m=>m.user_id===r.requested_by)?.display_name||t('staffNameLabel');return `<div class="upi-request"><span><b>${escapeHtml(r.new_upi_id)}</b><small>${t('requestedBy')} ${escapeHtml(requester)}</small></span><button type="button" data-upi-review="${r.id}" data-approved="true">${t('approve')}</button><button type="button" data-upi-review="${r.id}" data-approved="false">${t('reject')}</button></div>`}).join(''):`<p class="subheading">${t('noPendingUpi')}</p>`;document.querySelectorAll('[data-upi-review]').forEach(b=>b.onclick=()=>reviewUpiRequest(b.dataset.upiReview,b.dataset.approved==='true'));setShopSetupTab(activeTab)}
function ensureStaffManagementPanel(){if($('staffManagementPanel'))return;const panel=document.createElement('section');panel.id='staffManagementPanel';panel.innerHTML=`<h3 data-t="staffManagement"></h3><p class="subheading" data-t="staffManagementHint"></p><div id="addStaffForm"><label><span data-t="staffEmail"></span><input id="staffEmailInput" type="email" autocomplete="email" required data-ph="staffEmailPlaceholder"></label><label><span data-t="staffName"></span><input id="staffNameInput" required data-ph="staffNamePlaceholder"></label><button type="button" class="primary-button small" id="addStaffButton" data-t="addStaffMember"></button></div><h4 data-t="currentStaff"></h4><ul id="shopStaffList" class="staff-member-list"></ul>`;$('shopDetailsPanel').insertBefore(panel,$('registerShopPanel'));panel.querySelector('#addStaffButton').onclick=addShopStaff}
async function addShopStaff(event){event.preventDefault();const email=$('staffEmailInput').value.trim(),name=$('staffNameInput').value.trim(),button=$('addStaffButton');$('shopError').textContent='';if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){$('shopError').textContent=t('staffEmailRequired');return}if(!name){$('shopError').textContent=t('staffNameRequired');return}button.disabled=true;button.textContent=t('sendingStaffInvite');try{const response=await fetch(`${cloudConfig.SUPABASE_URL.replace(/\/$/,'')}/functions/v1/invite-shop-staff`,{method:'POST',headers:{'Content-Type':'application/json','apikey':cloudConfig.SUPABASE_PUBLISHABLE_KEY,'Authorization':`Bearer ${cloudSession.access_token}`},body:JSON.stringify({shop_id:cloudShopId,email,display_name:name})});const result=await response.json().catch(()=>({}));if(!response.ok){const error=new Error(result.error||'Staff invitation failed');error.status=response.status;throw error}$('staffEmailInput').value='';$('staffNameInput').value='';await loadCloudData();renderShopDialog();showToast(t(result.invited?'staffInvitationSent':'staffAdded'))}catch(error){$('shopError').textContent=/already assigned to this shop/i.test(error.message)?t('staffAlreadyAdded'):/No account found for this email/i.test(error.message)?t('staffAccountMissing'):error.status===404||error.status===501?t('staffInviteUnavailable'):error.status===502?t('staffInvitePartial'):uiError(error)}finally{const currentButton=$('addStaffButton');if(currentButton){currentButton.disabled=false;currentButton.textContent=t('addStaffMember')}}}
function validUpi(value){return /^[A-Za-z0-9._-]{2,100}@[A-Za-z0-9.-]{2,50}$/.test(value.trim())}
async function saveShopUpi(){const upi=$('shopUpiInput').value.trim();$('shopError').textContent='';if(!validUpi(upi)){$('shopError').textContent=t('validUpiError');return}try{if(cloudMember.role==='owner'){await cloudApi('rpc/set_shop_upi_id',{method:'POST',body:{p_shop_id:cloudShopId,p_upi_id:upi}});showToast(t('ownerUpiSaved'))}else{await cloudApi('shop_upi_change_requests',{method:'POST',body:{shop_id:cloudShopId,requested_by:cloudSession.user.id,new_upi_id:upi,status:'pending'},prefer:'return=minimal'});showToast(t('upiRequestSent'))}await loadCloudData();renderShopDialog()}catch(e){$('shopError').textContent=uiError(e)}}
async function reviewUpiRequest(id,approved){try{await cloudApi('rpc/review_shop_upi_change',{method:'POST',body:{p_request_id:id,p_approved:approved}});await loadCloudData();renderShopDialog();showToast(t(approved?'upiApproved':'upiRejected'))}catch(e){$('shopError').textContent=uiError(e)}}
async function registerShop(){const name=$('newShopName').value.trim(),upi=$('newShopUpi').value.trim();$('shopError').textContent='';if(!name){$('shopError').textContent=t('shopNameRequired');return}if(!validUpi(upi)){$('shopError').textContent=t('validUpiError');return}try{const businessId=cloudShops.find(s=>s.id===cloudShopId)?.business_id;if(!businessId)throw new Error(t('businessUnavailable'));const id=await cloudApi('rpc/register_business_shop',{method:'POST',body:{p_business_id:businessId,p_name:name,p_address:$('newShopAddress').value.trim()||null,p_phone:$('newShopPhone').value.trim()||null,p_upi_id:upi||null}});$('newShopName').value='';$('newShopUpi').value='';$('newShopAddress').value='';$('newShopPhone').value='';cloudShopId=id;localStorage.setItem('kb-active-shop-id',id);await loadCloudData();$('shopDialog').close();showToast(t('shopRegistered'))}catch(e){$('shopError').textContent=uiError(e)}}

async function switchShop(){const next=$('shopSelect').value;if(!next||next===cloudShopId)return;const previous=cloudShopId;cart=[];$('customerName').value='';$('customerMobile').value='';$('billDiscount').value=0;if(!navigator.onLine){try{await loadOfflineShop(next);showToast(t('offlineShopShown'))}catch(e){$('shopSelect').value=previous;showToast(uiError(e))}return}cloudShopId=next;localStorage.setItem('kb-active-shop-id',next);try{await loadCloudData();await syncPendingBills()}catch(e){if(e.isNetworkError){try{await loadOfflineShop(next)}catch(cacheError){cloudShopId=previous;$('shopSelect').value=previous;showToast(uiError(cacheError))}}else{cloudShopId=previous;$('shopSelect').value=previous;showToast(uiError(e))}}}
async function enterCloud(session,pendingOwner=null){cloudSession=session;localStorage.setItem('kb-auth-session',JSON.stringify(cloudSession));cloudMode=true;let ownerRegistered=false;try{if(pendingOwner){if(session.user?.email?.trim().toLowerCase()!==pendingOwner.email)throw new Error('Sign in with the email used to register this shop.');try{await cloudApi('rpc/register_owner',{method:'POST',body:{p_business_name:pendingOwner.businessName,p_shop_name:pendingOwner.shopName,p_display_name:pendingOwner.displayName,p_upi_id:pendingOwner.upiId,p_address:pendingOwner.address||null,p_phone:pendingOwner.phone||null}});ownerRegistered=true;localStorage.removeItem(PENDING_OWNER_KEY)}catch(e){if(!/already linked to a shop/i.test(e.message))throw e;localStorage.removeItem(PENDING_OWNER_KEY)}}await loadCloudData();$('authGate').hidden=true;$('appShell').hidden=false;$('signOut').hidden=false;showToast(ownerRegistered?AUTH_MESSAGES[lang].shopReady:`${t('signedIn')} · ${cloudMember.display_name}`);await syncPendingBills()}catch(e){if(e.isNetworkError&&openOfflineCache(session))return;cloudSession=null;cloudMode=false;cloudOnline=false;localStorage.removeItem('kb-auth-session');$('authError').textContent=uiError(e);$('appShell').hidden=true;$('authGate').hidden=false;throw e}}
async function signOut(){cloudLoadVersion++;try{if(cloudSession?.access_token)await fetch(`${cloudConfig.SUPABASE_URL.replace(/\/$/,'')}/auth/v1/logout`,{method:'POST',headers:{'apikey':cloudConfig.SUPABASE_PUBLISHABLE_KEY,'Authorization':`Bearer ${cloudSession.access_token}`}})}catch{}cloudSession=null;cloudMode=false;localStorage.removeItem('kb-auth-session');$('appShell').hidden=true;$('authGate').hidden=false;$('signOut').hidden=true;showAuthTab('login');$('loginPassword').value='';$('loginButton').disabled=false}
function showToast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500)}
function uiError(error){const message=error?.message||String(error);if(/null value in column "id" of relation "bills"|பில் சேமிப்புக்கு தரவுத்தளப் புதுப்பிப்பு தேவை/i.test(message))return t('billSchemaUpdate');if(/valid UPI ID is required|UPI ID is required|Enter a valid UPI ID|சரியான UPI ஐடி/i.test(message))return t('upiRequiredError');if(/no accessible shops were found|அணுகக்கூடிய கடைகள் இல்லை/i.test(message))return t('noAccessibleShops');if(/this account has not been approved for a shop yet|இந்தக் கணக்கு கடையுடன் இணைக்கப்படவில்லை/i.test(message))return t('shopNotApproved');if(/your session expired|உங்கள் அமர்வு முடிந்தது/i.test(message))return t('sessionExpired');if(/sign in with the email used to register|கடைப் பதிவு செய்த அதே மின்னஞ்சலில்/i.test(message))return t('sameEmailError');if(/could not save this offline bill on this device|இணையமற்ற பில்லைச் சேமிக்க முடியவில்லை/i.test(message))return t('offlineBillStorageError');return message}
function billSaveError(error){return uiError(error)}
function translateStaticUi(){
 const labels=[['.brand small','billingDesk'],['.mobile-brand small','productSubtitle'],['.shop-chip b','currentShop'],['.shop-chip small','chooseShop'],['.shop-switch>span','shop'],['#localShopSetupBtn','shopSetup'],['#signOut','signOut'],['#localShopDialog .eyebrow','shopSetup'],['#localShopDialog h2','yourShopDetails'],['#localShopDialog form>.subheading','shopDetailsBillHint'],['#cancelLocalShop','cancel'],['#saveLocalShop','saveDetails'],['#shopDialog .eyebrow','shopSetup'],['#registerShopPanel summary','requestedShopSetup'],['#registerShopButton','registerShop'],['#upiRequestsPanel h3','upiRequestsHeading']];
 labels.forEach(([selector,key])=>{const el=document.querySelector(selector);if(el)el.textContent=t(key)});
 const requestCount=cloudUpiRequests.length;
 $('shopSettingsButton').textContent=cloudMember?.role==='owner'&&requestCount?`${t('shopSetup')} · ${requestCount} ${t(requestCount===1?'approval':'approvals')}`:t('shopSetup');
 const fields=[['localShopName','shopName',''],['localShopUpi','upiId','upiShownQr'],['localShopAddress','address','optionalShort'],['localShopPhone','phone','optionalShort'],['shopUpiInput','upiId',''],['newShopName','shopName',''],['newShopUpi','upiId','upiRequiredShown'],['newShopAddress','address','optionalShort'],['newShopPhone','phone','optionalShort']];
 fields.forEach(([id,key,smallKey])=>{const span=$(id)?.closest('label')?.querySelector('span');if(!span)return;const text=[...span.childNodes].find(node=>node.nodeType===Node.TEXT_NODE);if(text)text.nodeValue=`${t(key)} `;const small=span.querySelector('small');if(small&&smallKey)small.textContent=t(smallKey)});
 const placeholders=[['localShopName','localShopNamePlaceholder'],['localShopUpi','localShopUpiPlaceholder'],['localShopAddress','localShopAddressPlaceholder'],['localShopPhone','localShopPhonePlaceholder'],['newItemName','itemNamePlaceholder'],['newItemTamil','tamilNamePlaceholder'],['newItemPrice','pricePlaceholder']];
 placeholders.forEach(([id,key])=>{if($(id))$(id).placeholder=t(key)});
 document.querySelectorAll('.dialog-close').forEach(button=>button.setAttribute('aria-label',t('close')));
 $('shopSelect').setAttribute('aria-label',t('selectShop'));
 $('staffMenu').title=t('chooseStaff');$('staffTop').title=t('chooseStaff');
 $('languageBtn').setAttribute('aria-label',t('changeLanguage'));
 updateSignedInRole();
}
function setLanguage(){
 document.documentElement.lang=lang==='ta'?'ta':'en';
 $('today').textContent=new Date().toLocaleDateString(lang==='ta'?'ta-IN':'en-IN',{weekday:'short',month:'short',day:'numeric'});
 document.querySelectorAll('[data-t]').forEach(el=>{const key=el.dataset.t;if(AUTH_TEXT[lang][key]||TEXT[lang][key])el.textContent=t(key)});
 document.querySelectorAll('[data-ph]').forEach(el=>el.placeholder=t(el.dataset.ph));
 $('languageBtn').textContent=t('language');$('authLanguageBtn').textContent=t('language');$('authLanguageBtn').setAttribute('aria-label',t('changeLanguage'));
 translateStaticUi();
 if($('defaultItemsDialog').open){renderDefaultItemOptions('catalogDefaultItems',catalogDefaultItems);$('defaultItemsHint').textContent=t(defaultPickerMode==='item'?'singleDefaultHint':'defaultCatalogHint');$('addSelectedDefaults').textContent=t(defaultPickerMode==='item'?'useDefaultItem':'addSelectedDefaults')}
 if($('shopDialog').open){if(cloudMode)renderShopDialog();if(!$('itemCatalogPanel').hidden)renderDefaultItemOptions('setupDefaultItems',setupDefaultItems)}
 showAuthTab($('registerForm').hidden?'login':'register');
 ['authError','registerError','shopError','localShopError'].forEach(id=>{const el=$(id);if(el.textContent)el.textContent=uiError({message:el.textContent})});
 renderAll();
}
function toggleLanguage(){lang=lang==='en'?'ta':'en';state.languageSelected=true;localStorage.setItem('kb-language',lang);persist();setLanguage()}
function setStaff(i){staffIndex=i;persist();$('staffName').textContent=STAFF[i].name;$('avatar').textContent=STAFF[i].initials;$('staffTop').textContent=STAFF[i].initials;$('staffDialog').close();renderBillNo()}
function renderBillNo(){const next=String(state.nextNo).padStart(4,'0');$('billNo').textContent=cloudMode?(cloudOnline?'KB-NEW':'OFFLINE'):'KB-'+next}
function recentCatalogItems(limit=5){const byId=new Map(state.items.map(item=>[item.id,item])),byName=new Map(state.items.map(item=>[item.name.trim().toLowerCase(),item])),recent=[],seen=new Set();const add=item=>{if(item&&!seen.has(item.id)){recent.push(item);seen.add(item.id)}};for(const item of [...cart].reverse())add(byId.get(item.id));for(const bill of [...state.bills].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))){for(const line of bill.items||[])add((line.id&&byId.get(line.id))||byName.get((line.name||'').trim().toLowerCase()));if(recent.length>=limit)return recent.slice(0,limit)}for(const item of state.items){add(item);if(recent.length>=limit)break}return recent.slice(0,limit)}
function renderCatalog(){const q=$('itemSearch').value.trim().toLowerCase(),canEdit=canManageCatalog(),matches=state.items.filter(i=>(i.name+' '+(i.tamil||'')).toLowerCase().includes(q)),list=q?matches:recentCatalogItems();$('catalog').innerHTML=list.length?list.map(i=>`<div class="catalog-item"><button class="catalog-add" data-add="${i.id}"><span class="item-thumb">◈</span><span class="catalog-item-info"><b>${escapeHtml(lang==='ta'&&i.tamil?i.tamil:i.name)}</b><small>${money(i.price)}</small></span><span class="add-circle">+</span></button>${canEdit?`<button type="button" class="catalog-edit" data-edit-item="${i.id}" aria-label="${t('editItem')} ${escapeHtml(i.name)}" title="${t('editItem')} ${escapeHtml(i.name)}">✎</button>`:''}</div>`).join(''):`<div class="catalog-empty">${t('noItems')}<br>${canEdit?`<button class="text-button" data-open-item>${t('addFirst')}</button>`:''}</div>`;$('catalog').querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addToCart(b.dataset.add));$('catalog').querySelectorAll('[data-edit-item]').forEach(b=>b.onclick=()=>openItemDialog(state.items.find(item=>item.id===b.dataset.editItem)));$('catalog').querySelectorAll('[data-open-item]').forEach(b=>b.onclick=openItemDialog)}
function addToCart(id){const item=state.items.find(i=>i.id===id);if(!item)return;const line=cart.find(x=>x.id===id);if(line)line.qty++;else cart.push({...item,qty:1,discount:0});renderBill()}
function changeQty(id,n){const line=cart.find(x=>x.id===id);if(!line)return;line.qty+=n;if(line.qty<1)cart=cart.filter(x=>x.id!==id);renderBill()}
function cartSubtotal(){return cart.reduce((s,x)=>s+x.price*x.qty-(x.discount||0),0)}function calc(){const subtotal=cartSubtotal(),billDiscount=Math.min(Math.max(Number($('billDiscount').value)||0,0),subtotal);return{subtotal,billDiscount,total:Math.max(0,subtotal-billDiscount)}}
function renderBill(){const el=$('billLines');if(!cart.length)el.innerHTML=`<div class="empty-state"><span class="basket">▱</span><b>${t('emptyBill')}</b><small>${t('emptyBillHint')}</small></div>`;else el.innerHTML=cart.map(x=>{const name=lang==='ta'&&x.tamil?x.tamil:x.name;return `<div class="bill-line"><div><div class="line-name">${escapeHtml(name)}</div><div class="line-sub">${money(x.price)} × ${x.qty}</div></div><div class="line-right"><div class="qty-control"><button data-qty="${x.id}" data-delta="-1" aria-label="${t('decreaseQty')} ${escapeHtml(name)}">−</button><span>${x.qty}</span><button data-qty="${x.id}" data-delta="1" aria-label="${t('increaseQty')} ${escapeHtml(name)}">+</button></div><div class="line-total">${money(x.price*x.qty)}</div><button class="remove-line" data-remove="${x.id}" title="${t('remove')}" aria-label="${t('removeBillItem')} ${escapeHtml(name)}">×</button></div></div>`}).join('');el.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>changeQty(b.dataset.qty,Number(b.dataset.delta)));el.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart=cart.filter(x=>x.id!==b.dataset.remove);renderBill()});const c=calc();$('subtotal').textContent=money(c.subtotal);$('discountTotal').textContent='− '+money(c.billDiscount);$('grandTotal').textContent=money(c.total);$('buttonTotal').textContent=money(c.total);renderCatalog()}
function renderItems(){const el=$('itemsTable'),canEdit=canManageCatalog();el.innerHTML=state.items.length?state.items.map(i=>`<div class="table-row"><span><b>${escapeHtml(i.name)}</b>${i.tamil?`<small>${escapeHtml(i.tamil)}</small>`:''}</span><b>${money(i.price)}${Number(i.price)===0?`<small>${t('zeroPriceHint')}</small>`:''}</b><span class="item-row-actions">${canEdit?`<button class="row-action" data-edit-item="${i.id}">${t('editItem')}</button><button class="row-action" data-delete-item="${i.id}">${t('deleteItem')}</button>`:''}</span></div>`).join(''):`<div class="history-empty">${t('noItems')}</div>`;el.querySelectorAll('[data-edit-item]').forEach(b=>b.onclick=()=>openItemDialog(state.items.find(item=>item.id===b.dataset.editItem)));el.querySelectorAll('[data-delete-item]').forEach(b=>b.onclick=async()=>{if(!confirm(t('removeConfirm')))return;try{if(cloudMode){await cloudApi(`items?id=eq.${b.dataset.deleteItem}&shop_id=eq.${cloudShopId}`,{method:'PATCH',body:{deleted:true,updated_at:new Date().toISOString()},prefer:'return=minimal'});await loadCloudData()}else{state.items=state.items.filter(i=>i.id!==b.dataset.deleteItem);persist();renderAll()}}catch(e){showToast(e.message)}})}
function renderHistory(){const el=$('historyTable');if(!state.bills.length){el.innerHTML=`<div class="history-empty">${t('emptyHistory')}</div>`;return}el.innerHTML=[...state.bills].reverse().map(b=>`<div class="history-row"><b>${b.pending?'PENDING · ':''}${escapeHtml(b.number)}</b><span>${escapeHtml(b.customer||t('customerWalkIn'))}</span><span>${new Date(b.createdAt).toLocaleDateString(lang==='ta'?'ta-IN':'en-IN')}</span><b>${money(b.total)}</b><span class="history-actions"><button class="row-action" data-print="${b.id}">${t('print')}</button>${b.mobile?`<button class="row-action" data-whatsapp="${b.id}">${t('sendWhatsApp')}</button>`:''}</span></div>`).join('');el.querySelectorAll('[data-print]').forEach(b=>b.onclick=()=>printBillSafely(state.bills.find(x=>x.id===b.dataset.print)));el.querySelectorAll('[data-whatsapp]').forEach(b=>b.onclick=()=>sendBillToCustomer(state.bills.find(x=>x.id===b.dataset.whatsapp)))}
function renderAll(){const canEdit=canManageCatalog();['addItemButton','browseDefaultItems','addItemShortcut'].forEach(id=>$(id).hidden=!canEdit);renderCatalog();renderBill();renderItems();renderHistory()}
async function saveBill(){
 if(!cart.length){showToast(t('itemRequired'));return}
 const c=calc();
 if(Number($('billDiscount').value)>c.subtotal){showToast(t('discountInvalid'));return}
 const draft={id:newId(),number:$('billNo').textContent,customer:$('customerName').value.trim(),mobile:$('customerMobile').value.trim(),staff:cloudMember?.display_name||STAFF[staffIndex].name,items:cart.map(x=>({...x})),subtotal:c.subtotal,discount:c.billDiscount,total:c.total,createdAt:new Date().toISOString()};
 let bill=draft;
 try{
  if(cloudMode){
   if(!navigator.onLine||!cloudOnline){bill=queueOfflineBill(draft)}
   else{
    try{
     const created=await cloudApi('rpc/create_shop_bill',{method:'POST',body:{p_shop_id:cloudShopId,p_customer_name:draft.customer||null,p_customer_mobile:draft.mobile||null,p_discount:draft.discount,p_items:draft.items.map(i=>({item_id:i.id,item_name:i.name,item_name_ta:i.tamil||null,quantity:i.qty,unit_price:i.price,line_total:i.qty*i.price})),p_client_request_id:draft.id}});
     bill={...draft,id:created.id,number:created.bill_number,createdAt:created.created_at};
     await loadCloudData();
    }catch(e){if(!e.isNetworkError)throw e;cloudOnline=false;bill=queueOfflineBill(draft)}
   }
  }else{state.bills.push(bill);state.nextNo++;persist()}
  cart=[];$('customerName').value='';$('customerMobile').value='';$('billDiscount').value=0;renderAll();renderBillNo();showToast(bill.pending?t('savedOffline'):t('saved'));setTimeout(()=>showAfterSave(bill),250);
 }catch(e){showToast(billSaveError(e))}
}
function queueOfflineBill(draft){const entry={local_id:draft.id,user_id:cloudSession.user.id,shop_id:cloudShopId,bill:{...draft,number:'OFF-'+draft.id.slice(0,8),pending:true,shopId:cloudShopId}};const rows=pendingBills();rows.push(entry);try{savePendingBills(rows)}catch(e){throw new Error(t('offlineBillStorageError'))}cloudOnline=false;const bill=entry.bill;state.bills.unshift(bill);updateSyncStatus();return bill}
function showAfterSave(bill){if(bill.mobile){if(confirm(t('whatsAppAfterSave')))sendBillToCustomer(bill);else printBillSafely(bill);return}if(confirm(t('sharePdfAfterSave')))shareBill(bill);else printBillSafely(bill)}
function receiptText(bill,shop){return [shop?.name||'Kadhar Bhavan',shop?.address||'',shop?.phone?`Ph: ${shop.phone}`:'',`Receipt: ${bill.number}`,bill.customer?`Customer: ${bill.customer}`:'',`Total: ${money(bill.total)}`,'Thank you for shopping with us!'].filter(Boolean).join('\n')}
function whatsAppPhone(mobile){let digits=(mobile||'').replace(/\D/g,'');if(digits.length===11&&digits.startsWith('0'))digits=digits.slice(1);return digits.length===10?`91${digits}`:digits}
function sendBillToCustomer(bill){const phone=whatsAppPhone(bill?.mobile);if(phone.length<8||phone.length>15){showToast(t('customerPhoneInvalid'));return}shareBill(bill)}
async function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src})}
async function createReceiptPdf(bill,shop){const width=720,margin=48,line=34;const qr=await qrDataUri(upiPaymentUri(bill,shop));const height=520+bill.items.length*line+(qr?300:0);const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,width,height);ctx.fillStyle='#17231d';ctx.textAlign='center';ctx.font='bold 34px "Noto Sans Tamil",Arial,sans-serif';ctx.fillText(t('receiptTitle'),width/2,70);ctx.font='20px Arial,sans-serif';ctx.fillText(shop?.name||'Kadhar Bhavan',width/2,108);ctx.font='16px Arial,sans-serif';let shopInfoY=132;if(shop?.address){ctx.fillText(shop.address,width/2,shopInfoY);shopInfoY+=22}if(shop?.phone){ctx.fillText(`Ph: ${shop.phone}`,width/2,shopInfoY);shopInfoY+=22}ctx.font='18px Arial,sans-serif';ctx.fillText(`Receipt ${bill.number}`,width/2,shopInfoY+10);ctx.textAlign='left';ctx.font='16px Arial,sans-serif';let y=shopInfoY+50;const meta=[new Date(bill.createdAt).toLocaleString(lang==='ta'?'ta-IN':'en-IN'),`Customer: ${bill.customer||t('customerWalkIn')}${bill.mobile?` · ${bill.mobile}`:''}`,`Staff: ${bill.staff||'Shop staff'}`];for(const text of meta){ctx.fillText(text,margin,y);y+=28}ctx.setLineDash([5,5]);ctx.beginPath();ctx.moveTo(margin,y);ctx.lineTo(width-margin,y);ctx.strokeStyle='#a8b0aa';ctx.stroke();ctx.setLineDash([]);y+=22;ctx.font='bold 18px Arial,sans-serif';ctx.fillText('ITEM',margin,y);ctx.textAlign='right';ctx.fillText('AMOUNT',width-margin,y);ctx.textAlign='left';y+=16;ctx.font='17px "Noto Sans Tamil",Arial,sans-serif';for(const item of bill.items){y+=25;const name=`${lang==='ta'&&item.tamil?item.tamil:item.name} × ${item.qty}`;ctx.fillText(name,margin,y);ctx.textAlign='right';ctx.fillText(money(item.price*item.qty),width-margin,y);ctx.textAlign='left';y+=8;ctx.strokeStyle='#e7ebe8';ctx.beginPath();ctx.moveTo(margin,y);ctx.lineTo(width-margin,y);ctx.stroke()}y+=34;for(const [label,value,bold] of [[t('subtotal'),money(bill.subtotal),false],[t('discount'),`− ${money(bill.discount)}`,false],[t('billTotal'),money(bill.total),true]]){ctx.font=`${bold?'bold ':''}${bold?25:18}px Arial,sans-serif`;ctx.fillText(label,margin,y);ctx.textAlign='right';ctx.fillText(value,width-margin,y);ctx.textAlign='left';y+=34}if(qr){try{const img=await loadImage(qr);ctx.textAlign='center';ctx.font='bold 20px Arial,sans-serif';ctx.fillText('Pay by UPI',width/2,y+12);ctx.drawImage(img,(width-210)/2,y+24,210,210);ctx.font='16px Arial,sans-serif';ctx.fillText(shop.upi_id||'',width/2,y+255);y+=280}catch{}}else if(shop?.upi_id){ctx.textAlign='center';ctx.font='16px Arial,sans-serif';ctx.fillText(`UPI: ${shop.upi_id}`,width/2,y+8);y+=30}ctx.textAlign='center';ctx.font='18px Arial,sans-serif';ctx.fillText(t('receiptThank'),width/2,Math.min(height-30,y+35));const jpeg=canvas.toDataURL('image/jpeg',.9);const bytes=window.KBReceiptPDF.buildPdf(jpeg,width,height);return new File([bytes],`Receipt-${String(bill.number).replace(/[^a-z0-9_-]/gi,'_')}.pdf`,{type:'application/pdf'})}
async function shareBill(bill){const shop=cloudMode?cloudShops.find(s=>s.id===(bill.shopId||cloudShopId)):loadLocalShop();const text=receiptText(bill,shop);try{const file=await createReceiptPdf(bill,shop);if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:`Receipt ${bill.number}`,text});return}const link=document.createElement('a');link.href=URL.createObjectURL(file);link.download=file.name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),60000);const phone=whatsAppPhone(bill.mobile);window.open(`https://wa.me${phone?`/${phone}`:''}?text=${encodeURIComponent(text)}`,'_blank','noopener,noreferrer');showToast(t('pdfDownloaded'))}catch(e){if(e.name==='AbortError')return;showToast(`${lang==='ta'?'PDF உருவாக்க முடியவில்லை':'Could not create PDF'}: ${uiError(e)}`)}}
function upiPaymentUri(bill,shop){if(!shop?.upi_id)return'';const params=new URLSearchParams({pa:shop.upi_id,pn:shop.name||'Kadhar Bhavan',am:Number(bill.total).toFixed(2),cu:'INR',tn:`Bill ${bill.number}`});return `upi://pay?${params.toString()}`}
async function qrDataUri(value){if(!value)return null;const Generator=window.QRCode;if(typeof Generator!=='function')throw new Error(t('qrUnavailable'));const host=document.createElement('div');host.setAttribute('aria-hidden','true');host.style.cssText='position:fixed;left:0;top:0;width:196px;height:196px;opacity:0;pointer-events:none;z-index:-1';document.body.append(host);try{new Generator(host,{text:value,width:196,height:196,correctLevel:Generator.CorrectLevel.M});return await new Promise((resolve,reject)=>{const started=Date.now();const check=()=>{const canvas=host.querySelector('canvas');if(canvas?.width&&canvas.height){try{resolve(canvas.toDataURL('image/png'));return}catch(error){reject(error);return}}const image=host.querySelector('img');if(image?.complete&&image.naturalWidth){resolve(image.src);return}if(Date.now()-started>3000){reject(new Error(t('qrUnavailable')));return}setTimeout(check,40)};check()})}finally{host.remove()}}
function printBillSafely(bill){printBill(bill).catch(error=>showToast(uiError(error)))}
async function printBill(b){const rows=b.items.map(i=>`<tr><td>${escapeHtml(lang==='ta'&&i.tamil?i.tamil:i.name)} × ${i.qty}</td><td>${money(i.price*i.qty)}</td></tr>`).join('');const shop=cloudMode?cloudShops.find(s=>s.id===(b.shopId||cloudShopId)):loadLocalShop();const uri=upiPaymentUri(b,shop);const qr=await qrDataUri(uri);const w=window.open('','_blank','width=480,height=720');if(!w){showToast('Allow pop-ups to print or save the PDF');return}w.document.write(`<!doctype html><html lang="${lang}"><meta charset="utf-8"><title>${escapeHtml(b.number)}</title><style>body{font:14px 'Noto Sans Tamil',Arial,sans-serif;color:#17231d;padding:24px;max-width:380px;margin:auto}h1{text-align:center;font-size:22px;margin-bottom:4px}p{text-align:center;color:#667;margin:4px 0 16px}.meta{font-size:12px;border-top:1px dashed #aaa;border-bottom:1px dashed #aaa;padding:10px 0}table{width:100%;border-collapse:collapse;margin:12px 0}td{padding:7px 0;border-bottom:1px solid #eee;font-size:12px}td:last-child{text-align:right}.total{font-weight:bold;font-size:18px}.thanks{text-align:center;margin-top:20px}.pay{text-align:center;margin-top:18px}.pay img{width:150px;height:150px}.pay small{display:block;font-size:10px;color:#667;margin-top:5px}@media print{button{display:none}}</style><body><h1>${t('receiptTitle')}</h1><p>${escapeHtml(b.number)}</p><div class="meta">${escapeHtml(shop?.name||'Kadhar Bhavan')}${shop?.address?`<br>${escapeHtml(shop.address)}`:''}${shop?.phone?`<br>Ph: ${escapeHtml(shop.phone)}`:''}${shop?.upi_id?`<br>UPI: ${escapeHtml(shop.upi_id)}`:''}\n<br>---<br>${new Date(b.createdAt).toLocaleString(lang==='ta'?'ta-IN':'en-IN')}<br>${escapeHtml(b.customer||t('customerWalkIn'))}${b.mobile?` · ${escapeHtml(b.mobile)}`:''}<br>${escapeHtml(b.staff)}</div><table>${rows}</table><table><tr><td>${t('subtotal')}</td><td>${money(b.subtotal)}</td></tr><tr><td>${t('discount')}</td><td>− ${money(b.discount)}</td></tr><tr class="total"><td>${t('billTotal')}</td><td>${money(b.total)}</td></tr></table>${qr?`<div class="pay"><b>Pay by UPI</b><br><img alt="UPI payment QR code" src="${qr}"><small>${escapeHtml(shop.upi_id)}</small></div>`:shop?.upi_id?`<p>UPI: ${escapeHtml(shop.upi_id)}</p>`:''}<p class="thanks">${t('receiptThank')}</p></body></html>`);w.document.close();setTimeout(()=>w.print(),300)}

function escapeHtml(str=''){return String(str).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function openItemDialog(item=null){if(!canManageCatalog()){showToast(t('ownerCatalogOnly'));return}editingItemId=item?.id||null;$('itemForm').reset();$('itemDialogHeading').textContent=t(editingItemId?'editItem':'addNewItem');$('itemDialogSubtitle').textContent=t('itemFormSubtitle');$('chooseItemFromDefaults').hidden=!!editingItemId;if(item){$('newItemName').value=item.name;$('newItemTamil').value=item.tamil||'';$('newItemPrice').value=item.price}$('itemDialog').showModal();setTimeout(()=>(editingItemId?$('newItemPrice'):$('newItemName')).focus(),50)}
async function saveItem(e){if(e.submitter?.id!=='saveItem')return;e.preventDefault();if(!canManageCatalog()){showToast(t('ownerCatalogOnly'));return}const name=$('newItemName').value.trim(),price=Number($('newItemPrice').value),tamil=$('newItemTamil').value.trim();if(!name||!Number.isFinite(price)||price<0)return;try{if(cloudMode){if(editingItemId)await cloudApi(`items?id=eq.${encodeURIComponent(editingItemId)}&shop_id=eq.${encodeURIComponent(cloudShopId)}`,{method:'PATCH',body:{name,name_ta:tamil||null,price,updated_at:new Date().toISOString()},prefer:'return=minimal'});else await cloudApi('items',{method:'POST',body:{shop_id:cloudShopId,name,name_ta:tamil||null,price,deleted:false,updated_at:new Date().toISOString()},prefer:'return=minimal'});await loadCloudData()}else if(editingItemId){state.items=state.items.map(item=>item.id===editingItemId?{...item,name,tamil,price}:item);persist();renderAll()}else{state.items.push({id:newId(),name,tamil,price});persist();renderAll()}$('itemDialog').close();editingItemId=null;showToast(t('itemSaved'))}catch(err){showToast(err.message)}}
function navigate(view){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+view));document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('pageTitle').textContent=view==='billing'?t('navBilling'):view==='items'?t('navItems'):t('navHistory');window.scrollTo({top:0,behavior:'smooth'})}
async function init(){
 $('today').textContent=new Date().toLocaleDateString('en-IN',{weekday:'short',month:'short',day:'numeric'});renderBillNo();
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
 $('shopManagementForm').onsubmit=e=>e.preventDefault();$('shopDialogClose').onclick=()=>$('shopDialog').close();$('shopSelect').onchange=switchShop;$('shopSettingsButton').onclick=()=>{renderShopDialog();$('shopError').textContent='';$('shopDialog').showModal()};$('shopDetailsTab').onclick=()=>setShopSetupTab('details');$('itemCatalogTab').onclick=()=>setShopSetupTab('catalog');$('addSetupDefaultItems').onclick=()=>addSelectedDefaultItems(setupDefaultItems,'shopDialog');$('saveShopUpi').onclick=saveShopUpi;$('registerShopButton').onclick=registerShop;$('itemSearch').oninput=renderCatalog;$('billDiscount').oninput=renderBill;$('saveBill').onclick=saveBill;
 $('clearBill').onclick=()=>{cart=[];$('billDiscount').value=0;renderBill();showToast(t('billCleared'))};
 $('addItemButton').onclick=()=>openItemDialog();$('addItemShortcut').onclick=()=>openItemDialog();$('itemForm').addEventListener('submit',saveItem);$('cancelItem').onclick=()=>$('itemDialog').close();$('chooseItemFromDefaults').onclick=()=>openDefaultItemsDialog('item');$('browseDefaultItems').onclick=()=>openDefaultItemsDialog();$('cancelDefaultItems').onclick=()=>$('defaultItemsDialog').close();$('addSelectedDefaults').onclick=()=>defaultPickerMode==='item'?useSelectedDefaultItem():addSelectedDefaultItems();
 $('staffMenu').onclick=$('staffTop').onclick=()=>{$('staffOptions').innerHTML=STAFF.map((s,i)=>`<button class="staff-option" data-staff="${i}"><span class="avatar">${s.initials}</span><span><b>${s.name}</b><small>${i===0?t('ownerRole'):t('staffNameLabel')}</small></span>${i===staffIndex?'✓':''}</button>`).join('');$('staffDialog').showModal();$('staffOptions').querySelectorAll('[data-staff]').forEach(b=>b.onclick=()=>setStaff(Number(b.dataset.staff)))};
 $('languageBtn').onclick=toggleLanguage;$('authLanguageBtn').onclick=toggleLanguage;$('signOut').onclick=signOut;
 $('staffName').textContent=STAFF[staffIndex].name;$('staffDisplayName').textContent=STAFF[staffIndex].name;$('avatar').textContent=STAFF[staffIndex].initials;$('staffTop').textContent=STAFF[staffIndex].initials;
 setLanguage();
 if(cloudEnabled){
   if(location.protocol!=='https:'&&!['localhost','127.0.0.1'].includes(location.hostname)){$('appShell').hidden=true;$('authGate').hidden=false;$('authError').textContent='Secure sign-in requires HTTPS. Use localhost for development or open the hosted HTTPS address.';$('loginButton').disabled=true;showAuthTab('login');return}
   cloudMode=true;$('appShell').hidden=true;$('authGate').hidden=false;$('signOut').hidden=true;
   showAuthTab(cloudSession?.access_token?'login':'register');
   $('loginForm').onsubmit=async e=>{e.preventDefault();$('authError').textContent='';$('authError').classList.remove('auth-success');$('loginButton').disabled=true;try{const email=$('loginEmail').value.trim().toLowerCase(),session=await authRequest('token?grant_type=password',{email,password:$('loginPassword').value});await enterCloud(session,pendingOwnerForEmail(email));$('loginPassword').value=''}catch(err){$('authError').textContent=/not been approved for a shop yet/i.test(err.message)?AUTH_MESSAGES[lang].noShopMembership:uiError(err);$('loginButton').disabled=false}};
   $('registerForm').onsubmit=async e=>{e.preventDefault();$('registerError').textContent='';$('registerError').classList.remove('auth-success');$('registerButton').disabled=true;$('registerButton').textContent=t('authRegistering');try{const email=$('regEmail').value.trim().toLowerCase(),profile={email,businessName:$('regShopName').value.trim(),shopName:$('regShopName').value.trim(),displayName:$('regDisplayName').value.trim(),upiId:$('regUpi').value.trim(),address:$('regAddress').value.trim(),phone:$('regPhone').value};savePendingOwner(profile);let session;try{session=await authRequest('signup',{email,password:$('regPassword').value})}catch(err){if(!/already registered|already exists/i.test(err.message))throw err;$('loginEmail').value=email;$('authError').textContent=AUTH_MESSAGES[lang].existingAccount;$('authError').classList.add('auth-success');showAuthTab('login');return}if(!session?.access_token){$('loginEmail').value=email;$('authError').textContent=AUTH_MESSAGES[lang].confirmEmail;$('authError').classList.add('auth-success');showAuthTab('login');return}await enterCloud(session,profile)}catch(err){$('registerError').textContent=uiError(err)}finally{$('registerButton').disabled=false;$('registerButton').textContent=t('authRegisterButton')}};
   if(cloudSession?.access_token){enterCloud(cloudSession).catch(()=>{$('loginButton').disabled=false})}
   setInterval(()=>{if(cloudMode&&navigator.onLine)loadCloudData().then(syncPendingBills).catch(e=>{if(!e.isNetworkError)showToast(e.message)})},20000);
   window.addEventListener('focus',()=>{if(cloudMode&&navigator.onLine)loadCloudData().then(syncPendingBills).catch(()=>{})});
   window.addEventListener('online',()=>{if(cloudMode)loadCloudData().then(syncPendingBills).catch(()=>{})});
   window.addEventListener('offline',()=>{if(cloudMode){cloudOnline=false;updateSyncStatus()}});
   if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{})
 } else {
   const hasShop=!!localStorage.getItem('kb-local-shop');
   if(hasShop){$('appShell').hidden=false;$('authGate').hidden=true;$('signOut').hidden=true;$('localShopSetupBtn').hidden=false;renderAll()}
   else{$('appShell').hidden=true;$('authGate').hidden=false;$('cloudRegFields').hidden=true;showAuthTab('register');$('registerForm').onsubmit=e=>{e.preventDefault();$('registerError').textContent='';const name=$('regShopName').value.trim(),upi=$('regUpi').value.trim(),addr=$('regAddress').value.trim(),ph=$('regPhone').value.trim();if(!name){$('registerError').textContent=t('shopNameRequired');return}if(!validUpi(upi)){$('registerError').textContent=t('upiRequiredError');return}saveLocalShopData({name,upi_id:upi,address:addr,phone:ph});$('authGate').hidden=true;$('appShell').hidden=false;$('localShopSetupBtn').hidden=false;renderAll();showToast(t('localWelcome'))}}
   if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{})
 }
}
init();
// Auth tab switcher
function showAuthTab(tab){
  const isReg=tab==='register';
  $('registerForm').hidden=!isReg;$('loginForm').hidden=isReg;
  $('tabRegister').classList.toggle('active',isReg);$('tabLogin').classList.toggle('active',!isReg);
  $('authHeading').textContent=t(isReg?'authRegisterHeading':'authLoginHeading');
}
function clearAuthMessages(){['registerError','authError'].forEach(id=>{const el=$(id);el.textContent='';el.classList.remove('auth-success')})}
$('tabRegister').onclick=()=>{clearAuthMessages();showAuthTab('register')};
$('tabLogin').onclick=()=>{clearAuthMessages();showAuthTab('login')};
$('switchToLogin').onclick=()=>{clearAuthMessages();showAuthTab('login')};
$('switchToRegister').onclick=()=>{clearAuthMessages();showAuthTab('register')};
// Local shop setup dialog
$('localShopSetupBtn').onclick=()=>{const s=loadLocalShop();$('localShopName').value=s.name||'';$('localShopUpi').value=s.upi_id||'';$('localShopAddress').value=s.address||'';$('localShopPhone').value=s.phone||'';$('localShopError').textContent='';$('localShopDialog').showModal()};
$('cancelLocalShop').onclick=()=>$('localShopDialog').close();
$('saveLocalShop').onclick=()=>{const name=$('localShopName').value.trim(),upi=$('localShopUpi').value.trim(),address=$('localShopAddress').value.trim(),phone=$('localShopPhone').value.trim();if(!name){$('localShopError').textContent=t('shopNameRequired');return}if(upi&&!validUpi(upi)){$('localShopError').textContent=t('validUpiError');return}saveLocalShopData({name,upi_id:upi,address,phone});$('localShopDialog').close();showToast(t('shopDetailsSaved'))};
